Definition strtoll_m1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s endp : word) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 18446744073709551615) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (bv_unsigned endp, bv_unsigned endp + 8)]%Z m m'
    /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' (bv_unsigned endp) [C8 (Z_to_bv 64 (bv_unsigned s + 2))]
    /\ bytes_at rsegs m' (bv_unsigned s) [Z_to_bv 8 45; Z_to_bv 8 49; Z_to_bv 8 0].

Definition strtoll_m1_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo : Z) (e0 : word),
  F = bvmap_empty -> fc = Z_to_bv 32 0 ->
  a2 = Z_to_bv 64 0 ->
  bv_unsigned sp mod 16 = 0 ->
  stk rsegs m lo (bv_unsigned sp) -> lo + STRTOLL_STACK <= bv_unsigned sp -> 0x200000 <= lo ->
  bv_unsigned sp <= 0x7fffffffffff ->
  bytes_at rsegs m (bv_unsigned a0) [Z_to_bv 8 45; Z_to_bv 8 49; Z_to_bv 8 0] ->
  0x200000 <= bv_unsigned a0 -> bv_unsigned a0 + 3 <= 0x7fffffffffff ->
  (bv_unsigned a0 + 3 <= lo \/ bv_unsigned sp <= bv_unsigned a0) ->
  rw_cells rsegs m (bv_unsigned a1) [C8 e0] ->
  0x200000 <= bv_unsigned a1 -> bv_unsigned a1 + 8 <= 0x7fffffffffff ->
  (bv_unsigned a1 + 8 <= lo \/ bv_unsigned sp <= bv_unsigned a1) ->
  (bv_unsigned a0 + 3 <= bv_unsigned a1 \/ bv_unsigned a1 + 8 <= bv_unsigned a0) ->
  CanaryReads m -> mem_inv rsegs m ->
  evt rsegs (strtoll_m1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc a0 a1 lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_STRTOLL) fc None m (seg_rom rsegs)).
